import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
const[label,priorFile,name,mode='frontend']=process.argv.slice(2);assert.match(label,/^[a-z][a-z0-9-]+$/);assert.match(name,/^compiled-only-root-[a-z0-9-]+$/);assert.ok(['frontend','activation','projection'].includes(mode));const evidence='docs/evidence/T20/postgres-speaker-focus',prior=JSON.parse(fs.readFileSync(priorFile,'utf8'));assert.equal(prior.allDirectChildrenClosed,true);assert.ok(path.resolve(prior.root).startsWith(path.resolve('storage/postgres-native-tests')+path.sep));const original=prior.compiledOnlyRoot,target=path.join(prior.root,name);assert.equal(fs.existsSync(target),false);
const hash=file=>createHash('sha256').update(fs.readFileSync(file)).digest('hex'),walk=dir=>fs.readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(dir,e.name)):[path.join(dir,e.name)]),originalDist=Object.fromEntries(walk(path.join(original,'dist')).map(file=>[path.relative(original,file).replaceAll('\\','/'),hash(file)])),changedBackend=Object.keys(originalDist).filter(f=>!f.startsWith('dist/web/')&&hash(f)!==originalDist[f]);
if(mode==='frontend')assert.deepEqual(changedBackend,[]);else{assert.ok(changedBackend.length>0);assert.ok(changedBackend.every(f=>['dist/api.mjs','dist/worker.mjs','dist/postgres-runtime.mjs'].includes(f)));}
fs.mkdirSync(target);fs.cpSync('dist',path.join(target,'dist'),{recursive:true,errorOnExist:true,force:false});for(const source of walk(path.join(original,'migrations'))){const rel=path.relative(original,source);assert.equal(hash(source),hash(rel));const dest=path.join(target,rel);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.copyFileSync(source,dest,fs.constants.COPYFILE_EXCL);}fs.cpSync(path.join(original,'scripts'),path.join(target,'scripts'),{recursive:true,errorOnExist:true,force:false});
for(const tool of prior.linkedTools){const src=path.join(original,'storage/tools',tool.file),dest=path.join(target,'storage/tools',tool.file);assert.equal(fs.statSync(src).size,tool.size);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.linkSync(src,dest);const h=createHash('sha256');for await(const b of fs.createReadStream(dest))h.update(b);assert.equal(h.digest('hex'),tool.sha256);}
for(const[file,sha]of Object.entries(originalDist))assert.equal(hash(path.join(original,file)),sha);const currentDist=Object.fromEntries(walk(path.join(target,'dist')).map(file=>[path.relative(target,file).replaceAll('\\','/'),hash(file)]));
fs.writeFileSync(evidence+'/'+label+'.json',JSON.stringify({result:'PASS',root:prior.root,priorFile,priorProofSHA256:hash(priorFile),mode,originalCompiledOnlyRoot:original,originalDist,currentCompiledOnlyRoot:target,currentDist,changedBackend,allOriginalCompiledFilesPreserved:true,newSqlMigrations:0,previousSuccessfulKillsRepeated:false},null,2)+'\n',{flag:'wx'});fs.writeFileSync(evidence+'/'+label+'-resume-input.json',JSON.stringify({...prior,compiledOnlyRoot:target,entrySHA256:Object.fromEntries(Object.keys(prior.entrySHA256).map(file=>[file,hash(file)]))},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({result:'PASS',root:prior.root,originalFiles:Object.keys(originalDist).length,currentFiles:Object.keys(currentDist).length,mode,changedBackend}));
